/**
 * @file assets/sounds/villain-laughs.js
 * @about Two real recorded cartoon villain laughs for Shadowspine: high, cackly "HA-HA-HA-HAAA!"s. They come from the "Evil Laughs" pack by Eldritch Grim on OpenGameArt, which is CC0 (public domain: free to use, credit is kind but not required). Each one is trimmed, made about as loud as the other, and squeezed into a small mono MP3 written right into this file, so the game stays one self-contained page.
 * @provides Kit.sounds.villainLaughs: [{ id, seconds, from (the name in the original pack), src (a data: URL of the MP3) }], Kit.sounds.credits
 * @requires nothing
 *
 * Source: https://opengameart.org/content/evil-laughs-pack ("Laugh 4" and "Laugh 7"), license: https://creativecommons.org/publicdomain/zero/1.0/
 * Kit.voices.evilLaugh plays these when they're in the game (taking turns), and falls back to its made-in-code laugh when they aren't.
 * To swap in a different laugh: trim it, make it mono, encode it as a small MP3 (about 64 kbps), and replace a src. Keep seconds accurate.
 */
(function (Kit) {
  "use strict";
  Kit.sounds = Kit.sounds || {};
  Kit.sounds.villainLaughs = [
    { id: "cackle", seconds: 3.1, from: "Laugh 4", src: "data:audio/mpeg;base64," },
    { id: "big-cackle", seconds: 4.94, from: "Laugh 7", src: "data:audio/mpeg;base64," }
  ];
  Kit.sounds.credits = (Kit.sounds.credits || []).concat(["Villain laughs: \"Evil Laughs\" pack by Eldritch Grim, OpenGameArt.org (CC0)"]);
})(window.Kit = window.Kit || {});
